28	func (m settingsModel) update(msg tea.Msg) (settingsModel, tea.Cmd) {
29		if m.state == nil || m.state.Store == nil {
30			return m, nil
31		}
32	
33		keyMsg, ok := msg.(tea.KeyMsg)
34		if !ok {
35			return m, nil
36		}
37	
38		var changed settingsChangedMsg
39		hasChange := false
40	
41		switch {
42		case key.Matches(keyMsg, settingsKeyMap.Mode):
43			next := cycleMode(m.state.Store.Mode)
44			changed.mode = &next
45			hasChange = true
46	
47		case key.Matches(keyMsg, settingsKeyMap.Policy):
48			next := cyclePolicy(m.state.Store.ActivationPolicy)
49			changed.activationPolicy = &next
50			hasChange = true
51	
52		case key.Matches(keyMsg, settingsKeyMap.MaxUp):
53			next := m.state.Store.MaxInjected + 1
54			if next > 10 {
55				next = 10
56			}
57			changed.maxInjected = &next
58			hasChange = true
59	
60		case key.Matches(keyMsg, settingsKeyMap.MaxDown):
61			next := m.state.Store.MaxInjected - 1
62			if next < 1 {
63				next = 1
64			}
65			changed.maxInjected = &next
66			hasChange = true
67	
68		case key.Matches(keyMsg, settingsKeyMap.ScopeRepo):
69			scopes := toggleScope(m.state.Store.InjectionScopes, memoryloop.ScopeKindRepo)
70			changed.injectionScopes = &scopes
71			hasChange = true
72	
73		case key.Matches(keyMsg, settingsKeyMap.ScopeMe):
74			scopes := toggleScope(m.state.Store.InjectionScopes, memoryloop.ScopeKindMe)
75			changed.injectionScopes = &scopes
76			hasChange = true
77	
78		case key.Matches(keyMsg, settingsKeyMap.ScopeBranch):
79			scopes := toggleScope(m.state.Store.InjectionScopes, memoryloop.ScopeKindBranch)
80			changed.injectionScopes = &scopes
81			hasChange = true
82	
83		case key.Matches(keyMsg, settingsKeyMap.Threshold):
84			next := cycleThreshold(m.state.Store.GenerationThreshold)
85			changed.generationThreshold = &next
86			hasChange = true
87		}
88	
89		if hasChange {
90			return m, func() tea.Msg { return changed }
91		}
92		return m, nil
93	}
