253	func cycleMode(current memoryloop.Mode) memoryloop.Mode {
254		for i, m := range modeOrder {
255			if m == current {
256				return modeOrder[(i+1)%len(modeOrder)]
257			}
258		}
259		return memoryloop.ModeOff
260	}
261	
262	func cyclePolicy(current memoryloop.ActivationPolicy) memoryloop.ActivationPolicy {
263		for i, p := range policyOrder {
264			if p == current {
265				return policyOrder[(i+1)%len(policyOrder)]
266			}
267		}
268		return memoryloop.ActivationPolicyReview
269	}
270	
271	func cycleThreshold(current string) string {
272		if current == "" {
273			current = "balanced"
274		}
275		for i, t := range thresholdOrder {
276			if t == current {
277				return thresholdOrder[(i+1)%len(thresholdOrder)]
278			}
279		}
280		return "balanced"
281	}
