283	// effectiveInjectionScopes returns the active scopes, defaulting to all if empty.
284	func effectiveInjectionScopes(scopes []memoryloop.ScopeKind) []memoryloop.ScopeKind {
285		if len(scopes) == 0 {
286			return memoryloop.DefaultInjectionScopes()
287		}
288		return scopes
289	}
