300	// toggleScope adds or removes a scope kind from the list.
301	// Starts from DefaultInjectionScopes if the current list is empty.
302	func toggleScope(current []memoryloop.ScopeKind, target memoryloop.ScopeKind) []memoryloop.ScopeKind {
303		if len(current) == 0 {
304			current = memoryloop.DefaultInjectionScopes()
305		}
306		// Check if target is already present.
307		for i, s := range current {
308			if s == target {
309				// Remove it (but don't allow removing all scopes).
310				if len(current) <= 1 {
311					return current
312				}
313				return append(current[:i], current[i+1:]...)
314			}
315		}
316		// Add it.
317		return append(current, target)
318	}
