368		if m.state == nil || m.state.Store == nil {
369			return m, nil
370		}
371		if msg.mode != nil {
372			m.state.Store.Mode = *msg.mode
373		}
374		if msg.activationPolicy != nil {
375			m.state.Store.ActivationPolicy = *msg.activationPolicy
376		}
377		if msg.maxInjected != nil {
378			m.state.Store.MaxInjected = *msg.maxInjected
379		}
380		if msg.injectionScopes != nil {
381			m.state.Store.InjectionScopes = *msg.injectionScopes
382		}
383		if msg.generationThreshold != nil {
384			m.state.Store.GenerationThreshold = *msg.generationThreshold
385		}
386		if err := m.saveState(); err != nil {
387			return m, func() tea.Msg { return flashMsg{text: fmt.Sprintf("save failed: %v", err), success: false} }
388		}
389		m.pushState()
390		return m, nil
