299	func runMemoryLoopRefresh(ctx context.Context, w io.Writer, last int, scopeArg, branchArg string, debug bool) error {
300		worktreeRoot, err := paths.WorktreeRoot(ctx)
301		if err != nil {
302			return fmt.Errorf("not in a git repository: %w", err)
303		}
304	
305		cfg, cfgErr := LoadEntireSettings(ctx)
306		if cfgErr != nil {
307			return fmt.Errorf("load settings: %w", cfgErr)
308		}
309	
310		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
311		if err != nil {
312			return fmt.Errorf("open insights cache: %w", err)
313		}
314		defer func() { _ = idb.Close() }()
315	
316		renderMemoryLoopRefreshProgress(w, "Refreshing cache...")
317		refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // non-fatal
318	
319		scope, err := resolveMemoryLoopScope(ctx, scopeArg, branchArg)
320		if err != nil {
321			return err
322		}
323	
324		switch scope.Mode {
325		case memoryLoopScopeRepo, memoryLoopScopeBranch:
326			renderMemoryLoopRefreshProgress(w, fmt.Sprintf("Scope: %s (branch: %s)", scope.Mode, scope.Branch))
327		case memoryLoopScopeMe:
328			renderMemoryLoopRefreshProgress(w, fmt.Sprintf("Scope: me (%s)", scope.OwnerID))
329		}
330	
331		renderMemoryLoopRefreshProgress(w, "Loading scoped sessions...")
332		rows, err := queryMemoryLoopRows(ctx, idb, scope, last)
333		if err != nil {
334			return fmt.Errorf("query sessions: %w", err)
335		}
336	
337		if settings.IsSummarizeEnabled(ctx) && len(rows) > 0 {
338			renderMemoryLoopRefreshProgress(w, "Backfilling summaries for scoped sessions...")
339			backfillSessionRows(ctx, w, idb, rows, debug)
340		}
341	
342		// Re-query to pick up backfilled data.
343		rows, err = queryMemoryLoopRows(ctx, idb, scope, last)
344		if err != nil {
345			return fmt.Errorf("query sessions: %w", err)
346		}
347		if len(rows) == 0 {
348			if err := renderEmptyMemoryLoopScopeMessage(ctx, w, idb, scope); err != nil {
349				return err
350			}
351			return nil
352		}
353	
