224	func buildGeneratedRecordsDetailed(resp generateResponse, input GenerateInput, now time.Time) ([]MemoryRecord, GenerationStats) {
225		cfg := input.ThresholdConfig
226		if cfg.MinStrength == 0 {
227			cfg = ResolveGenerationThreshold("balanced", nil)
228		}
229		validSourceIDs := buildValidSourceIDs(input.Sessions)
230		orderedKeys := make([]string, 0, len(resp.Records))
231		bestByKey := make(map[string]generatedCandidate)
232		stats := GenerationStats{}
233		for _, item := range resp.Records {
234			title := cleanGeneratedText(item.Title)
235			body := cleanGeneratedText(item.Body)
236			if title == "" || body == "" {
237				continue
238			}
239			kind := item.Kind
240			if kind == "" {
241				kind = KindRepoRule
242			}
243			confidence := normalizeConfidence(item.Confidence)
244			strength := clamp(item.Strength, 1, 5)
245			if confidenceRank(confidence) < confidenceRank(cfg.MinConfidence) || strength < cfg.MinStrength {
246				stats.FilteredWeakCount++
247				continue
248			}
249			if cfg.GenericFilter && isGenericGeneratedCandidate(title, body) {
250				stats.FilteredGenericCount++
251				continue
252			}
253	
254			record := MemoryRecord{
255				ID:               MakeRecordID(kind, title),
256				Kind:             kind,
257				Title:            title,
258				Body:             body,
259				SkillName:        strings.TrimSpace(item.SkillName),
260				SkillPath:        strings.TrimSpace(item.SkillPath),
261				Why:              strings.TrimSpace(item.Why),
262				Evidence:         trimSlice(item.Evidence, 3),
263				SourceSessionIDs: trimSlice(item.SourceSessionIDs, input.SourceWindow),
264				Confidence:       confidence,
265				Strength:         strength,
266				Status:           StatusCandidate,
267				Origin:           OriginGenerated,
268				Fingerprint:      FingerprintForRecord(kind, title, body),
269				CreatedAt:        now,
270				UpdatedAt:        now,
271			}
272			if isLiteralReviewEvidence(record, input.Analysis.ReviewDerivedRules) {
273				stats.FilteredGenericCount++
274				continue
275			}
276			if !passesEvidenceGate(record, item.SourceSignal, input.Analysis, validSourceIDs, cfg.EvidenceSessions, cfg.SingletonPolicy) {
277				stats.FilteredNoEvidenceCount++
278				continue
279			}
280	
281			key := normalizedGeneratedCandidateKey(kind, title, body)
282			next := generatedCandidate{
283				record:            record,
